COMMENT ON COLUMN RA.STUDENT_ID IS 'the id numbe representing each student';
COMMENT ON COLUMN RA.CAPABILITY IS 'the capability of student on research(Evaluated by the professor)';
ALTER TABLE RA MODIFY (CAPABILITY ANNOTATIONS (ADD value_description 'higher --> higher research ability / capability'));
COMMENT ON COLUMN RA.PROF_ID IS 'professor who advises this student';
ALTER TABLE RA MODIFY (PROF_ID ANNOTATIONS (ADD value_description 'this value may be repetitive since one professor may advise many students in this semestercommonsense evidence:if a professor advise > 2 students in this semester, it means this professor''s research work is heavyor: this professor''s popularity on research is higher'));
COMMENT ON COLUMN RA.SALARY IS 'the salary of this student.';
ALTER TABLE RA MODIFY (SALARY ANNOTATIONS (ADD value_description 'med: average salaryhigh: higher salary than otherslow: lower salaryfree: unpaid RA'));
COMMENT ON COLUMN COURSE.COURSE_ID IS 'unique id representing the course';
COMMENT ON COLUMN COURSE."NAME" IS 'name of the course';
COMMENT ON COLUMN COURSE.CREDIT IS 'credit of the course';
ALTER TABLE COURSE MODIFY (CREDIT ANNOTATIONS (ADD value_description 'commonsense evidence:higher means more important'));
COMMENT ON COLUMN COURSE.DIFF IS 'difficulty of the course';
ALTER TABLE COURSE MODIFY (DIFF ANNOTATIONS (ADD value_description 'commonsense evidence:higher --> more difficultsmaller --> less difficult'));
COMMENT ON COLUMN PROF.PROF_ID IS 'unique id for professors';
COMMENT ON COLUMN PROF.GENDER IS 'gender of the professor';
COMMENT ON COLUMN PROF.FIRST_NAME IS 'the first name of the professor';
COMMENT ON COLUMN PROF.LAST_NAME IS 'the last name of the professor';
ALTER TABLE PROF MODIFY (LAST_NAME ANNOTATIONS (ADD value_description 'commonsense evidence:full name: first name, last name'));
COMMENT ON COLUMN PROF.EMAIL IS 'email of the professor';
COMMENT ON COLUMN PROF.POPULARITY IS 'popularity of the professor';
ALTER TABLE PROF MODIFY (POPULARITY ANNOTATIONS (ADD value_description 'commonsense evidence:higher --> more popular'));
COMMENT ON COLUMN PROF.TEACHINGABILITY IS 'the teaching ability of the professor';
ALTER TABLE PROF MODIFY (TEACHINGABILITY ANNOTATIONS (ADD value_description 'commonsense evidence:higher --> more teaching ability, his / her lectures may have better quality'));
COMMENT ON COLUMN PROF.GRADUATE_FROM IS 'the school where the professor graduated from';
COMMENT ON COLUMN REGISTRATION.COURSE_ID IS 'the id of courses';
COMMENT ON COLUMN REGISTRATION.STUDENT_ID IS 'the id of students';
COMMENT ON COLUMN REGISTRATION.GRADE IS 'the grades that the students acquire in this course';
ALTER TABLE REGISTRATION MODIFY (GRADE ANNOTATIONS (ADD value_description 'commonsense evidence: A: excellent -- 4 B: good -- 3 C: fair -- 2 D: poorly pass -- 1 null or empty: this student fails to pass this course gpa of students for this semester = sum (credits x grade) / sum (credits)'));
COMMENT ON COLUMN REGISTRATION.SAT IS 'student satisfaction with the course';
COMMENT ON COLUMN STUDENT.STUDENT_ID IS 'the unique id to identify students';
COMMENT ON COLUMN STUDENT.F_NAME IS 'the first name of the student';
COMMENT ON COLUMN STUDENT.L_NAME IS 'the last name of the student';
ALTER TABLE STUDENT MODIFY (L_NAME ANNOTATIONS (ADD value_description 'commonsense evidence:full name: f_name, l_name'));
COMMENT ON COLUMN STUDENT.PHONE_NUMBER IS 'phone number';
COMMENT ON COLUMN STUDENT.EMAIL IS 'email';
COMMENT ON COLUMN STUDENT.INTELLIGENCE IS 'intelligence of the student';
ALTER TABLE STUDENT MODIFY (INTELLIGENCE ANNOTATIONS (ADD value_description 'higher --> more intelligent'));
COMMENT ON COLUMN STUDENT.GPA IS 'gpa';
COMMENT ON COLUMN STUDENT."TYPE" IS 'type of the student';
ALTER TABLE STUDENT MODIFY ("TYPE" ANNOTATIONS (ADD value_description ' TPG: taught postgraduate student(master) RPG: research postgraduate student (master) UG: undergraduate student(bachelor)commonsense evidence:both TPG and RPG are students pursuing a masters degree; UG are students pursuing the bachelor degree'));